19	export function DateCalendar({
20	  selected,
21	  onSelect,
22	  onClose,
23	  accentColor = "#84cc16",
24	  accentFg = "#000",
25	  locale = "lt",
26	  minDate,
27	}: DateCalendarProps) {
28	  const [calMonth, setCalMonth] = useState(() => startOfMonth(selected ?? new Date()));
29	  const dnLocale = locale === "lt" ? ltLocale : locale === "ru" ? ruLocale : enUS;
30	  const today = new Date();
31	  today.setHours(0, 0, 0, 0);
32	  const minD = minDate ?? today;
