/**
 * @summary Get court availability for a date
 */
export const getGetCourtAvailabilityUrl = (
  id: number,
  params: GetCourtAvailabilityParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/courts/${id}/availability?${stringifiedParams}`
    : `/api/courts/${id}/availability`;
};

export const getCourtAvailability = async (
  id: number,
  params: GetCourtAvailabilityParams,
  options?: RequestInit,
): Promise<AvailabilityResponse> => {
  return customFetch<AvailabilityResponse>(
    getGetCourtAvailabilityUrl(id, params),
    {
      ...options,
      method: "GET",
    },
  );
};

export const getGetCourtAvailabilityQueryKey = (
  id: number,
  params?: GetCourtAvailabilityParams,
) => {
  return [
    `/api/courts/${id}/availability`,
    ...(params ? [params] : []),
  ] as const;
};

export const getGetCourtAvailabilityQueryOptions = <
  TData = Awaited<ReturnType<typeof getCourtAvailability>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  params: GetCourtAvailabilityParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getCourtAvailability>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetCourtAvailabilityQueryKey(id, params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getCourtAvailability>>
  > = ({ signal }) =>
    getCourtAvailability(id, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getCourtAvailability>>,
    TError,
    TData

